277:    private PlaywrightProviderCampaign open(UUID campaignId,
278:            Set<SofascoreEndpointType> allowedEndpoints, LiveProviderGroupTracker.Authority groupAuthority) {
279:        Objects.requireNonNull(campaignId, "campaignId");
280:        Set<SofascoreEndpointType> allowlist = Set.copyOf(
281:                Objects.requireNonNull(allowedEndpoints, "allowedEndpoints"));
282:        if (allowlist.isEmpty() || !IMPLEMENTED_ENDPOINTS.containsAll(allowlist)) {
283:            throw new PlaywrightProviderException(PlaywrightProviderFailure.INVALID_ENDPOINT);
284:        }
285:        if (!properties.isEnabled()) {
286:            throw new PlaywrightProviderException(PlaywrightProviderFailure.DISABLED);
287:        }
288:        requireSupervisorOpen();
289:        if (active.get() != null) {
290:            throw new PlaywrightProviderException(
291:                    PlaywrightProviderFailure.CAMPAIGN_ALREADY_ACTIVE);
292:        }
293:
294:        StopTombstones tombstones = stopTombstonesFor(allowlist);
295:        if (tombstones.blocks(campaignId)) {
296:            throw new PlaywrightProviderException(PlaywrightProviderFailure.OPERATOR_STOP);
297:        }
298:        Path workerJar = requireWorkerJar();
299:        CampaignState state = new CampaignState(campaignId, allowlist, groupAuthority);
300:        if (!active.compareAndSet(null, state)) {
301:            throw new PlaywrightProviderException(
302:                    PlaywrightProviderFailure.CAMPAIGN_ALREADY_ACTIVE);
303:        }
304:        try {
305:            requireStartupAllowed(state, tombstones, campaignId);
306:            ServerSocket server = openLoopbackServer();
307:            state.server = server;
308:            requireStartupAllowed(state, tombstones, campaignId);
309:            String token = newToken();
310:            requireStartupAllowed(state, tombstones, campaignId);
311:            Process process = startWorker(workerJar, server.getLocalPort(), token);
312:            Instant processStartedAt = process.info().startInstant().orElse(null);
313:            state.publishProcess(process, processStartedAt);
314:            if (processStartedAt == null) {
315:                process.destroyForcibly();
316:                throw new PlaywrightProviderException(
317:                        PlaywrightProviderFailure.RUNTIME_FAILURE);
318:            }
319:            requireStartupAllowed(state, tombstones, campaignId);
320:
321:            Socket socket = server.accept();
322:            requireStartupAllowed(state, tombstones, campaignId);
323:            requireExactLoopbackPeer(socket);
324:            socket.setTcpNoDelay(true);
325:            socket.setKeepAlive(false);
326:            socket.setSoTimeout(toMillis(properties.getStartupTimeout()));
327:            DataInputStream input = new DataInputStream(
328:                    new BufferedInputStream(socket.getInputStream()));
329:            DataOutputStream output = new DataOutputStream(
330:                    new BufferedOutputStream(socket.getOutputStream()));
331:            state.attach(socket, input, output);
332:            authenticate(input, token);
333:            requireStartupAllowed(state, tombstones, campaignId);
334:            startWorkerRuntime(input, output,state.j3PauseCapable);
335:            requireStartupAllowed(state, tombstones, campaignId);
336:            ProcessRegistration registration = state.processRegistration.getNow(null);
337:            ProcessTreeSnapshot initialInventory = captureInitialProcessInventory(
338:                    state,
339:                    Objects.requireNonNull(registration, "process registration"));
340:            if (!initialInventory.isExactFor(registration)) {
341:                throw new PlaywrightProviderException(
342:                        PlaywrightProviderFailure.RUNTIME_FAILURE);
343:            }
344:            requireStartupAllowed(state, tombstones, campaignId);
345:            socket.setSoTimeout(toMillis(properties.getRequestTimeout().plusSeconds(1)));
346:            closeQuietly(server);
347:            state.server = null;
348:            requireStartupAllowed(state, tombstones, campaignId);
349:            state.phase.set(CampaignPhase.READY);
350:            return new Campaign(this, state);
351:        }
352:        catch (PlaywrightProviderException exception) {
353:            state.publishNoProcess();
354:            PlaywrightProviderException reported = stoppedDuringOpen(
355:                    state, tombstones, campaignId)
356:                            && exception.failure() != PlaywrightProviderFailure.OPERATOR_STOP
357:                                    ? new PlaywrightProviderException(
358:                                            PlaywrightProviderFailure.OPERATOR_STOP,
359:                                            exception)
360:                                    : exception;
361:            throw terminateFailedOpen(state, reported);
362:        }
363:        catch (SocketTimeoutException exception) {
364:            state.publishNoProcess();
365:            boolean stopped = stoppedDuringOpen(state, tombstones, campaignId);
366:            throw terminateFailedOpen(state, new PlaywrightProviderException(
367:                    stopped
368:                            ? PlaywrightProviderFailure.OPERATOR_STOP
369:                            : PlaywrightProviderFailure.STARTUP_FAILED,
370:                    exception));
371:        }
372:        catch (IOException | RuntimeException exception) {
373:            state.publishNoProcess();
374:            boolean stopped = stoppedDuringOpen(state, tombstones, campaignId);
375:            throw terminateFailedOpen(state, new PlaywrightProviderException(
376:                    stopped
377:                            ? PlaywrightProviderFailure.OPERATOR_STOP
378:                            : PlaywrightProviderFailure.STARTUP_FAILED,
379:                    exception));
380:        }
381:    }
