768:    private void requireDispatchScope(CampaignState state,PlaywrightProviderRequest request,J3ProviderSubOperation scope) {
769:        if(scope==null) {
770:            if(state.j3Scope!=null)throw new PlaywrightProviderException(PlaywrightProviderFailure.INVALID_REQUEST);
771:            return;
772:        }
773:        if(!scope.equals(state.j3Scope) || Thread.currentThread()!=state.controlOwner
774:                || request.endpoint()!=SofascoreEndpointType.SCHEDULED_EVENTS || !scope.date().equals(request.date())
775:                || request.page()<=state.lastJ3Page || request.page()>35 || request.ifNoneMatch().isPresent()
776:                || !clock.instant().plus(properties.getRequestTimeout()).plusSeconds(5).isBefore(scope.deadline()))
777:            throw new PlaywrightProviderException(PlaywrightProviderFailure.INVALID_REQUEST);
778:    }
