1243:    private Process startWorker(Path workerJar, int port, String token) throws IOException {
1244:        Path java = Path.of(
1245:                System.getProperty("java.home"),
1246:                "bin",
1247:                isWindows() ? "java.exe" : "java").toAbsolutePath().normalize();
1248:        ProcessBuilder builder = new ProcessBuilder(
1249:                java.toString(),
1250:                "-Xms32m",
1251:                "-Xmx" + properties.getMaximumHeapMib() + "m",
1252:                "-jar",
1253:                workerJar.toString());
1254:        builder.redirectInput(ProcessBuilder.Redirect.PIPE);
1255:        builder.redirectOutput(ProcessBuilder.Redirect.DISCARD);
1256:        builder.redirectError(ProcessBuilder.Redirect.DISCARD);
1257:        Map<String, String> environment = builder.environment();
1258:        environment.clear();
1259:        copySafeEnvironment(environment);
1260:        environment.put(SKIP_BROWSER_DOWNLOAD, "1");
1261:        environment.put(IPC_PORT, Integer.toString(port));
1262:        environment.put(IPC_TOKEN, token);
1263:        if (properties.isLoopbackQualification()) {
1264:            environment.put(LOOPBACK_QUALIFICATION, "true");
1265:            environment.put(LOOPBACK_ORIGIN, properties.getLoopbackOrigin());
1266:        }
1267:        return processStarter.start(builder);
1268:    }
